colors=[1,7,9]
patterns={1:[[1,0,1],[1,1,1],[1,1,0]],7:[[1,0,1],[0,1,1],[1,0,1]],9:[[0,1,1],[0,1,0],[1,1,1]]}
out=[[4]*19 for _ in range(7)]
for c0,col in zip([1,7,13],colors):
    for rr in range(5):
        for cc in range(5):
            out[rr+1][c0+cc]=col
    for rr in range(3):
        for cc in range(3):
            out[rr+2][c0+1+cc]=4 if patterns[col][rr][cc] else col
print('\n'.join(' '.join(map(str,r)) for r in out))
